<?php
require_once __DIR__.'/gia.php';require_once __DIR__.'/thanh_toan.php';
function reserve_vehicle(array $u,string $vin,string $coupon,string $key,?int $quote=null): string {
 must($u['quyen']==='KHACH_HANG','Chỉ khách hàng có thể đặt cọc.',403);must((bool)preg_match('/^[a-f0-9]{32}$/D',$key),'Mã yêu cầu không hợp lệ.');
 return transaction(function()use($u,$vin,$coupon,$key,$quote){$x=db_one('SELECT * FROM xe WHERE so_khung_vin=? FOR UPDATE',[$vin]);must((bool)$x,'Xe không tồn tại.');$existing=db_one('SELECT * FROM hop_dong WHERE tai_khoan_id=? AND ma_yeu_cau=?',[$u['id'],$key]);if($existing){must($existing['so_khung_vin']===$vin,'Mã yêu cầu đã dùng cho xe khác.');return $existing['so_hop_dong'];}
 expire_vin_locked($x);$x=db_one('SELECT * FROM xe WHERE so_khung_vin=?',[$vin]);must($x['trang_thai']==='SAN_SANG_BAN'&&!other_active($vin,''),'Xe đang được giữ hoặc đã bán.');must(db_one('SELECT 1 FROM showroom WHERE ma_showroom=? AND hoat_dong=1',[$x['ma_showroom']]),'Showroom đang ngừng hoạt động.');$price=tinh_gia($x['ma_cau_hinh'],$coupon,true);$chat=null;
 if($quote){must($coupon==='','Báo giá thỏa thuận không cộng thêm mã giảm giá.');$q=db_one('SELECT b.*,h.khach_hang_id FROM bao_gia b JOIN hoi_thoai_chat h ON h.ma_hoi_thoai=b.ma_hoi_thoai WHERE b.id=? FOR UPDATE',[$quote]);must($q&&(int)$q['khach_hang_id']===(int)$u['id']&&$q['ma_cau_hinh']===$x['ma_cau_hinh']&&strtotime($q['hieu_luc_den'])>time(),'Báo giá không hợp lệ hoặc hết hạn.');$price['gia']=$price['tong']=vnd($q['gia_chot']);$price['giam']=0;$chat=$q['ma_hoi_thoai'];}
 $id=uid('HD');$deposit=min((int)setting('deposit_vnd'),$price['tong']);$deadline=date('Y-m-d H:i:s',time()+(int)setting('hold_minutes')*60);$staff=db_one('SELECT p.nhan_vien_id FROM phan_cong_khach p JOIN tai_khoan t ON t.id=p.nhan_vien_id JOIN pham_vi_showroom s ON s.tai_khoan_id=p.nhan_vien_id WHERE p.khach_hang_id=? AND s.ma_showroom=? AND t.trang_thai=\'HOAT_DONG\' AND t.quyen=\'NHAN_VIEN\' LIMIT 1',[$u['id'],$x['ma_showroom']]);
 execute("INSERT INTO hop_dong(so_hop_dong,tai_khoan_id,nhan_vien_id,so_khung_vin,han_giu_vin,tien_dat_coc,tong_gia_tri,ma_yeu_cau,ma_showroom_chot,gia_von_chot,gia_truoc_giam,tien_giam,ma_km,bao_gia_id,ma_hoi_thoai) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",[$id,$u['id'],$staff['nhan_vien_id']??null,$vin,$deadline,$deposit,$price['tong'],$key,$x['ma_showroom'],$x['gia_von'],$price['gia'],$price['giam'],$price['ma_km'],$quote,$chat]);
 execute("UPDATE xe SET trang_thai='DANG_GIU' WHERE so_khung_vin=?",[$vin]);execute('INSERT INTO moc_thanh_toan(so_hop_dong,ten_moc,so_tien_luy_ke,han_thanh_toan) VALUES(?,?,?,?),(?,?,?,NULL)',[$id,'Đặt cọc',$deposit,$deadline,$id,'Thanh toán đủ trước bàn giao',$price['tong']]);
 $cart=db_one('SELECT so_luong FROM gio_hang WHERE tai_khoan_id=? AND ma_cau_hinh=? FOR UPDATE',[$u['id'],$x['ma_cau_hinh']]);if($cart){if((int)$cart['so_luong']>1)execute('UPDATE gio_hang SET so_luong=so_luong-1 WHERE tai_khoan_id=? AND ma_cau_hinh=?',[$u['id'],$x['ma_cau_hinh']]);else execute('DELETE FROM gio_hang WHERE tai_khoan_id=? AND ma_cau_hinh=?',[$u['id'],$x['ma_cau_hinh']]);}
 audit('DAT_COC','hop_dong',$id,null,['vin'=>$vin,'gia'=>$price['tong']]);return $id;
 });
}
